public sealed class FluentIcon : Control
{
    public static readonly DependencyProperty KindProperty = DependencyProperty.Register(nameof(Kind), typeof(string), typeof(FluentIcon), new FrameworkPropertyMetadata("circle", FrameworkPropertyMetadataOptions.AffectsRender, Changed));
    public static readonly DependencyProperty FilledProperty = DependencyProperty.Register(nameof(Filled), typeof(bool), typeof(FluentIcon), new FrameworkPropertyMetadata(false, FrameworkPropertyMetadataOptions.AffectsRender, Changed));
    public string Kind { get => (string)GetValue(KindProperty); set => SetValue(KindProperty, value); }
    public bool Filled { get => (bool)GetValue(FilledProperty); set => SetValue(FilledProperty, value); }
    public FluentIcon() { Width = Height = 16; IsHitTestVisible = false; Focusable = false; }
    public FluentIcon(string kind, double size = 16) : this() { Kind = kind; Width = Height = size; }
    private static void Changed(DependencyObject sender, DependencyPropertyChangedEventArgs args)
    {
        var icon = (FluentIcon)sender;
        if (icon.IsLoaded && FluentMotion.Enabled)
            icon.BeginAnimation(OpacityProperty, new DoubleAnimation(.55, 1, TimeSpan.FromMilliseconds(167)));
    }
    protected override void OnRender(DrawingContext drawing)
    {
        var key = Filled && Paths.ContainsKey(Kind + "-filled") ? Kind + "-filled" : Kind;
        if (!Paths.TryGetValue(key, out var data)) return;
        if (!Geometries.TryGetValue(key, out var geometry)) { geometry = Geometry.Parse(data); geometry.Freeze(); Geometries.Add(key, geometry); }
        drawing.PushTransform(new ScaleTransform(ActualWidth / 20, ActualHeight / 20));
        drawing.DrawGeometry(Foreground, null, geometry);
        drawing.Pop();
    }
